import type { FieldIR, ProtocolIR, TypeIR } from './ir.js';

export const GENERATED_HEADER =
  'Code generated by packages/protocol/scripts/gen.ts from packages/protocol/schemas. DO NOT EDIT.';

const q = (s: string): string => `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
const key = (s: string): string => (/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(s) ? s : q(s));

function tsType(t: TypeIR): string {
  switch (t.k) {
    case 'string':
      return 'string';
    case 'integer':
      return 'number';
    case 'boolean':
      return 'boolean';
    case 'literal':
      return typeof t.value === 'string' ? q(t.value) : String(t.value);
    case 'array': {
      const inner = tsType(t.items);
      return /^[A-Za-z0-9_]+$/.test(inner) ? `${inner}[]` : `(${inner})[]`;
    }
    case 'named':
      return t.name;
  }
}

const field = (f: FieldIR): string =>
  `  ${key(f.json)}${f.required ? '' : '?'}: ${tsType(f.type)};`;

export function emitTs(ir: ProtocolIR, protocolHash: string): string {
  const out: string[] = [`// ${GENERATED_HEADER}`, ''];
  out.push(
    '/** SHA-256 of the canonical schema bundle. Sent in hello; the server accepts only known hashes. */',
  );
  out.push(`export const PROTOCOL_HASH = ${q(protocolHash)};`, '');

  out.push('/** schemas/limits.json */');
  out.push('export const LIMITS = {');
  for (const l of ir.limits) out.push(`  ${key(l.name)}: ${String(l.value)},`);
  out.push('} as const;', '');

  out.push('/** schemas/defs/error-codes.json (meanings: docs/PROTOCOL.md) */');
  out.push('export const ERROR_CODES = {');
  for (const e of ir.errorCodes) {
    out.push(
      `  ${key(e.code)}: { from: ${q(e.from)}, retryable: ${String(e.retryable)}, fatal: ${String(e.fatal)}, agentAction: ${q(e.agentAction)} },`,
    );
  }
  out.push('} as const;', '');

  for (const n of [...ir.named.values()]) {
    if (n.k === 'enum') {
      out.push(`export type ${n.name} = ${n.values.map(q).join(' | ')};`, '');
    } else if (n.fields.length === 0) {
      out.push(`export type ${n.name} = Record<string, never>;`, '');
    } else {
      out.push(`export interface ${n.name} {`, ...n.fields.map(field), '}', '');
    }
  }

  for (const m of ir.messages) {
    const name = `${m.payload.replace(/Payload$/, '')}Message`;
    out.push(`export interface ${name} {`);
    out.push('  v: 1;', `  type: ${q(m.type)};`, '  id: string;', '  ts: string;');
    if (m.corr === 'required') out.push('  corr: string;');
    if (m.corr === 'optional') out.push('  corr?: string;');
    out.push(`  payload: ${m.payload};`, '}', '');
  }

  out.push('export interface MessageMap {');
  for (const m of ir.messages) {
    out.push(`  ${key(m.type)}: ${m.payload.replace(/Payload$/, '')}Message;`);
  }
  out.push('}', '');
  out.push('export type MessageType = keyof MessageMap;');
  out.push('export type ProtocolMessage = MessageMap[MessageType];');
  out.push("export type PayloadOf<T extends MessageType> = MessageMap[T]['payload'];");
  const sentBy = (side: 'agent' | 'server'): string =>
    ir.messages
      .filter((m) => m.from === side || m.from === 'both')
      .map((m) => q(m.type))
      .join(' | ');
  out.push(`export type AgentMessageType = ${sentBy('agent')};`);
  out.push(`export type ServerMessageType = ${sentBy('server')};`, '');

  out.push('export const MESSAGE_REGISTRY = {');
  for (const m of ir.messages) {
    out.push(
      `  ${key(m.type)}: { from: ${q(m.from)}, corr: ${q(m.corr)}, replies: [${m.replies.map(q).join(', ')}], timeoutMs: ${m.timeoutMs === null ? 'null' : String(m.timeoutMs)} },`,
    );
  }
  out.push('} as const;', '');

  out.push('export interface HttpBodyMap {');
  for (const h of ir.http) out.push(`  ${key(h.name)}: ${h.body};`);
  out.push('}', '');
  out.push('export type HttpBodyName = keyof HttpBodyMap;', '');
  out.push('export const HTTP_REGISTRY = {');
  for (const h of ir.http) {
    out.push(
      `  ${key(h.name)}: { from: ${q(h.from)}, method: ${q(h.method)}, path: ${q(h.path)}, replies: [${h.replies.map(q).join(', ')}] },`,
    );
  }
  out.push('} as const;', '');

  out.push('export interface ManifestMap {');
  for (const m of ir.manifests) out.push(`  ${key(m.kind)}: ${m.type};`);
  out.push('}', '');
  out.push('export type ManifestKind = keyof ManifestMap;', '');
  return out.join('\n');
}

export function emitTsBundle(canonical: string): string {
  return [
    `// ${GENERATED_HEADER}`,
    '',
    '/** Canonical JSON of the schema bundle (hash input). Parsed once by the codec. */',
    `export const BUNDLE_CANONICAL = ${JSON.stringify(canonical)};`,
    '',
  ].join('\n');
}
